import { config } from './config.js';
import { dataService, features, rules } from './data.js';
import { button, pageHeader, sectionHeader, newsCard, featureCard, notice, table, dateLabel, badge } from './components.js';
export async function home() {
  const articles = await dataService.getNews();
  return `<section class="hero"><div class="hero-image"></div><div class="container hero-content"><div class="hero-kicker"><span></span> A NEW REALM. A NEW BEGINNING.</div><h1>The world you know.<br><em>The adventure you miss.</em></h1><p>Some worlds never leave you.<br>Return to Azeroth, and write your next chapter.</p><div class="hero-actions">${button('Begin your adventure <span aria-hidden="true">→</span>', '#/play')}${button('Discover the realm <span aria-hidden="true">↗</span>', '#/server', 'outline')}</div><div class="hero-details"><span>WRATH OF THE LICH KING</span><i></i><span>3.3.5a</span><i></i><span>A FRESH START</span></div></div><div class="hero-bottom container"><span>YOUR NEXT CHAPTER STARTS HERE</span><a href="#latest" data-scroll="latest">EXPLORE <span aria-hidden="true">↓</span></a></div></section><section class="realm-strip"><div class="container realm-strip-inner"><div class="realm-identity"><span class="status-dot"></span><div><strong>${config.realm}</strong><span>Realm in development</span></div>${badge('PRE-LAUNCH')}</div><div class="realm-stat"><span>EXPANSION</span><strong>Wrath of the Lich King</strong></div><div class="realm-stat"><span>EXPERIENCE</span><strong>${config.rates} <small>proposed rates</small></strong></div><div class="realm-stat"><span>MAX LEVEL</span><strong>${config.level}</strong></div><a class="text-link" href="#/server">Realm details <span>↗</span></a></div></section><section class="section container" id="latest">${sectionHeader(`THE LATEST FROM ${config.name.toUpperCase()}`, 'A world in the making.', '<a class="text-link" href="#/news">All updates <span>→</span></a>')}<div class="news-grid">${articles.map(newsCard).join('')}</div><p class="content-note">Preview journal · These articles illustrate the future news experience.</p></section><section class="features-section"><div class="container section">${sectionHeader('MORE THAN A DESTINATION', 'It’s everything along the way.')}<div class="feature-grid">${features.map(featureCard).join('')}</div></div></section><section class="container section"><div class="journey-panel"><div><p class="eyebrow">YOUR STORY IS STILL UNWRITTEN</p><h2>Every legend starts<br>with a first step.</h2><p>New to the realm? We’ll help you find your way.<br>Everything you need, in one simple guide.</p></div><div class="journey-action"><span class="journey-mark" aria-hidden="true">Λ</span>${button('How to get started <span aria-hidden="true">→</span>', '#/play')}<span>No subscription. Just adventure.</span></div></div></section>`;
}
export async function newsPage(category = 'All') {
  const articles = await dataService.getNews();
  return `${pageHeader('THE REALM JOURNAL', 'Stories from a world in the making.', 'Announcements, development notes, and the people behind the adventure.')}<section class="container page-section"><div class="tabs" role="group" aria-label="News categories">${['All', 'Announcement', 'Development', 'Community'].map(c => `<button class="tab ${category === c ? 'is-active' : ''}" data-category="${c}" aria-pressed="${category === c}">${c}</button>`).join('')}</div>${notice('These are demonstration articles for the website preview. Launch details have not been announced.')}<div class="news-grid">${articles.filter(a => category === 'All' || a.category === category).map(newsCard).join('')}</div></section>`;
}
export async function articlePage(id) {
  const article = (await dataService.getNews()).find(a => a.id === id);
  if (!article) return notFound();
  return `<article class="container article page-section"><a class="text-link" href="#/news">← Back to the journal</a><div class="news-meta">${badge(article.category)}<time datetime="${article.date}">${dateLabel(article.date)}</time></div><h1>${article.title}</h1><p class="lead">${article.excerpt}</p><img class="article-image" src="https://images.unsplash.com/${article.image}?auto=format&fit=crop&w=1500&q=85" alt="A natural landscape evoking the world of the realm"><p>${article.body}</p>${notice('Demonstration article · This content is an example of future project updates.')}</article>`;
}
export async function serverPage() {
  const realm = await dataService.getRealm();
  return `${pageHeader('MEET YOUR NEXT HOME', 'A familiar world. A fresh perspective.', 'An independent realm concept inspired by the journey, the challenge, and the community.')}<section class="container page-section"><div class="server-grid"><div class="panel"><div class="panel-heading"><h2>${config.realm}</h2>${badge(realm.status)}</div><dl class="details-list">${[['Expansion', config.expansion], ['Client version', config.version], ['Maximum level', config.level], ['Experience rate', `${config.rates} (proposed)`], ['Online players', 'Not connected'], ['Launch date', 'To be announced'], ['Realm address', config.connection]].map(([k,v]) => `<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl></div><div class="server-intro"><p class="eyebrow">THE PHILOSOPHY</p><h2>Worth exploring.<br>Worth coming home to.</h2><p>We believe the best memories happen when the world gives you a reason to slow down, team up, and take the long way home.</p><p>A carefully considered Wrath-era foundation is our starting point. Detailed features and progression plans will be shared as development continues.</p>${button('Explore the getting-started guide →', '#/play', 'outline')}</div></div>${notice('This is a website foundation. Realm settings are illustrative and no live game server is connected.')}<div class="feature-grid">${features.map(featureCard).join('')}</div></section>`;
}
export function playPage() {
  const steps = [['Create your account', 'Your adventure begins with an account. Registration will open when the realm is ready for testing.', button('Account preview →', '#/account', 'outline')], ['Prepare your client', `You’ll need a compatible ${config.version} client. An official download source and installation instructions will be announced before launch.`, '<span class="badge">DOWNLOAD NOT YET AVAILABLE</span>'], ['Connect to the realm', 'The connection address and exact configuration instructions will appear here when testing opens.', '<div class="connection-value">Realm address <strong>To be announced</strong></div>'], ['Step into the world', 'Launch the game, sign in, and create your first character. We’ll publish any final steps before the realm opens.', '<span class="badge">LAUNCH DATE TO BE ANNOUNCED</span>']];
  return `${pageHeader('THE FIRST STEP IS YOURS', 'Your next adventure starts here.', 'Four simple steps. One world of possibilities.')}<section class="container page-section narrow">${notice('The realm is in development. Account creation, downloads, and game connections are not available yet.')}<div class="steps">${steps.map(([title, text, action], i) => `<article class="step panel"><span class="step-number">0${i + 1}</span><div><h2>${title}</h2><p>${text}</p>${action}</div></article>`).join('')}</div></section>`;
}
export async function rankingsPage(category = 'players', query = '') {
  const rows = await dataService.getRankings(category);
  const filtered = rows.filter(row => row.some(value => String(value).toLowerCase().includes(query.toLowerCase())));
  return `${pageHeader('MAKE YOUR MARK', 'The names behind the legends.', 'A little friendly competition. A lot of stories worth telling.')}<section class="container page-section">${notice('Demonstration rankings with fictional players and guilds. No live game data is connected.')}<div class="ranking-toolbar"><div class="tabs" role="group" aria-label="Ranking category">${[['players', 'Players'], ['guilds', 'Guilds'], ['pvp', 'PvP arena']].map(([id, label]) => `<button class="tab ${category === id ? 'is-active' : ''}" data-ranking="${id}" aria-pressed="${category === id}">${label}</button>`).join('')}</div><label class="search-label"><span class="sr-only">Search rankings</span><input type="search" id="ranking-search" placeholder="Search ${category === 'guilds' ? 'guilds' : 'players'}…" value=""></label></div><div id="ranking-results">${table(category === 'guilds' ? ['Rank', 'Guild', 'Faction', 'Members', 'Score'] : ['Rank', 'Player', 'Class', 'Faction', 'Guild', 'Rating'], filtered)}</div><p class="content-note">Showing ${rows.length} example ${category === 'guilds' ? 'guilds' : 'players'} · Preview season</p></section>`;
}
export function accountPage(mode = 'login') {
  return `${pageHeader('YOUR PLACE IN THE WORLD', 'Welcome, adventurer.', 'Your account will be the home for your journey.')}<section class="container page-section account-section"><div class="panel account-panel"><div class="tabs" role="group" aria-label="Account action">${['login', 'register'].map(m => `<button class="tab ${m === mode ? 'is-active' : ''}" data-account="${m}" aria-pressed="${m === mode}">${m === 'login' ? 'Sign in' : 'Create account'}</button>`).join('')}</div>${notice('Interface preview only. No account will be created and credentials are never sent or saved.')}<form id="account-form"><label for="username">Username</label><input id="username" name="username" autocomplete="username" minlength="3" maxlength="24" required placeholder="Your adventurer name">${mode === 'register' ? '<label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" required placeholder="you@example.com">' : ''}<label for="password">Password</label><input id="password" name="password" type="password" autocomplete="${mode === 'register' ? 'new-password' : 'current-password'}" minlength="8" required placeholder="At least 8 characters">${mode === 'register' ? '<label class="checkbox-label"><input type="checkbox" required> I have read the <a href="#/rules">realm rules</a>.</label>' : ''}<button class="button button--primary" type="submit">Preview ${mode === 'login' ? 'sign in' : 'registration'} <span>→</span></button><p id="form-message" role="status"></p></form></div><div class="account-copy"><span class="brand-symbol" aria-hidden="true">Λ</span><h2>A world worth<br>coming home to.</h2><p>Manage your journey, follow your progress, and stay connected. Account services will arrive with the realm.</p></div></section>`;
}
export function rulesPage() { return `${pageHeader('A BETTER WORLD, TOGETHER', 'Good adventures start with respect.', 'A shared foundation for a welcoming, fair, and lasting community.')}<section class="container page-section narrow">${notice('Proposed community guidelines. Final rules and enforcement policies will be published before launch.')}<div class="rules-list">${rules.map(([title, text], i) => `<article class="rule"><span class="step-number">0${i + 1}</span><div><h2>${title}</h2><p>${text}</p></div></article>`).join('')}</div></section>`; }
export const notFound = () => `${pageHeader('OFF THE BEATEN PATH', 'This trail ends here.', 'We couldn’t find that page. There’s still a whole world to discover.')}<div class="container page-section">${button('Return home →', '#/')}</div>`;
